func init() {
	sort.Strings(tokens)
}
func isAllowStr(str string) (illegalStr string, ok bool) {
	strs := strings.Split(str, "")
	for _, s := range strs {
		if !binarySearch(s) {
			return s, false
		}
	}
	return illegalStr, true
}

func binarySearch(s string) (ok bool) {
	start := 0
	end := len(tokens) - 1
	for start <= end {
		mid := (start + end) / 2
		if s < tokens[mid] {
			end = mid - 1
		} else if s > tokens[mid] {
			start = mid + 1
		} else {
			return true
		}
	}
	return
}

func formatStmt(stmt *Stmt) (err error) {
	for _, arg := range stmt.Args {
		argStr := fmt.Sprint(arg)
		if s, ok := isAllowStr(argStr); !ok {
			return errors.New(s + " is illegal Str")
		}
		stmt.Sql = strings.Replace(stmt.Sql, "?", fmt.Sprintf("'%s'", argStr), 1)
	}
	stmt.Args = []interface{}{}
	return
}
